h(), true)\n\t},\n\tbeforeDestroy() {\n\t\tif (this.request !== null) {\n\t\t\tthis.request.abort()\n\t\t}\n\t},\n\tmethods: {\n\t\topen(path, fallbackToRoot = false) {\n\t\t\tif (this.request !== null) {\n\t\t\t\tthis.request.abort()\n\t\t\t}\n\t\t\tthis.request = new AbortController()\n\t\t\tthis.loading = true\n\t\t\tthis.error = false\n\t\t\taxios.get(generateUrl('/apps/mediadc/api/v1/folders'), {\n\t\t\t\tparams: { path },\n\t\t\t\tsignal: this.request.signal,\n\t\t\t}).then(res => {\n\t\t\t\tthis.path = res.data.path\n\t\t\t\tthis.folders = res.data.folders\n\t\t\t\tthis.filter = ''\n\t\t\t\tthis.loading = false\n\t\t\t}).catch(err => {\n\t\t\t\tif (isCancel(err)) {\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tif (fallbackToRoot && path !== '/') {\n\t\t\t\t\tthis.open('/')\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tconsole.debug(err)\n\t\t\t\tthis.error = true\n\t\t\t\tthis.loading = false\n\t\t\t})\n\t\t},\n\t\tchoose() {\n\t\t\tsetLastPath(this.path)\n\t\t\tthis.$emit('choose', this.path)\n\t\t},\n\t\tcancel() {\n\t\t\tthis.$emit('cancel')\n\t\t},\n\t},\n}\n</script>\n\n<style scoped>\n.directory-picker {\n\tdisplay: flex;\n\tflex-direction: column;\n\tgap: 12px;\n\tpadding: 20px;\n\theight: 60vh;\n}\n\n.directory-picker__breadcrumbs {\n\tdisplay: flex;\n\tflex-wrap: wrap;\n\tgap: 4px;\n}\n\n.directory-picker__crumb {\n\tmargin: 0;\n\tpadding: 2px 8px;\n}\n\n.directory-picker__crumb:not(:last-child)::after {\n\tcontent: ' /';\n}\n\n.directory-picker__list {\n\tflex: 1;\n\toverflow-y: auto;\n}\n\n.directory-picker__folder {\n\tdisplay: flex;\n\talign-items: center;\n\tgap: 8px;\n\twidth: 100%;\n\tmargin: 0;\n\tborder: none;\n\tborder-radius: var(--border-radius);\n\tbackground: transparent;\n\ttext-align: start;\n}\n\n.directory-picker__folder:hover {\n\tbackground: var(--color-background-hover);\n}\n\n.directory-picker__actions {\n\tdisplay: flex;\n\tjustify-content: flex-end;\n\tgap: 8px;\n}\n</style>\n"],"sourceRoot":""}]);
